# Zoogi Roll ground cracks / craters (Oct 22, fx/cracks). Original procedural look: Voronoi stone cells with glowing seams,
# cells raised into a crater rim by world position offset, soft irregular masked edge, panned glow, light shafts + sparks.
# Textures are generated by Scripts/cracks/gen_tex.py (numpy + Pillow, run in that folder; no third-party art). Re-runnable.
# Run: Scripts\run_python.ps1-style headless editor (-run=pythonscript -script=<abs path to this file>).
# Builds /Game/VFX/Cracks/{T_ZoogiCrackCells, T_ZoogiCrackSoft, M_ZoogiCrack (master), MI_ZoogiCrack_<Style>,
#   M_ZoogiCrackShaft, M_ZoogiCrackSpark, MI_ZoogiCrackSpark_<Style>, NS_ZoogiCrackSparks_<Style>} used by AZoogiCrackFX.
import unreal, os
EAL = unreal.EditorAssetLibrary
MEL = unreal.MaterialEditingLibrary
AT = unreal.AssetToolsHelpers.get_asset_tools()
L = unreal.ZoogiFXLibrary
ROOT = '/Game/VFX/Cracks'
HERE = os.path.dirname(os.path.abspath(__file__))
TPL = '/Niagara/DefaultAssets/Templates/Emitters/'
LC = unreal.LinearColor
MP = unreal.MaterialProperty
unreal.AssetRegistryHelpers.get_asset_registry().scan_paths_synchronous(['/Niagara', '/Game/VFX'], True)
def log(s): unreal.log('CRACKSFX ' + s)

# style: crack colour, inner (bowl) colour, stone colour, emissive  (keep in sync with ZoogiCrackFX.cpp Palette())
STYLES = {
    'Lava':    (LC(1.0, 0.30, 0.04, 1), LC(1.0, 0.12, 0.02, 1), LC(0.15, 0.13, 0.12, 1), 14.0),
    'Ice':     (LC(0.10, 0.60, 1.0, 1), LC(0.20, 0.70, 1.0, 1), LC(0.10, 0.18, 0.30, 1), 10.0),
    'Warm':    (LC(1.0, 0.55, 0.20, 1), LC(1.0, 0.40, 0.10, 1), LC(0.40, 0.38, 0.35, 1), 8.0),
    'Fire':    (LC(1.0, 0.22, 0.03, 1), LC(1.0, 0.45, 0.05, 1), LC(0.19, 0.16, 0.14, 1), 16.0),
    'Frost':   (LC(0.30, 0.75, 1.0, 1), LC(0.50, 0.85, 1.0, 1), LC(0.14, 0.22, 0.34, 1), 12.0),
    'Shock':   (LC(0.25, 0.55, 1.0, 1), LC(0.70, 0.85, 1.0, 1), LC(0.21, 0.23, 0.29, 1), 18.0),
    'Void':    (LC(0.60, 0.18, 1.0, 1), LC(0.30, 0.05, 0.70, 1), LC(0.14, 0.11, 0.19, 1), 14.0),
    'Titan':   (LC(1.0, 0.48, 0.12, 1), LC(1.0, 0.30, 0.05, 1), LC(0.50, 0.50, 0.52, 1), 10.0),
    'Crystal': (LC(0.30, 0.95, 1.0, 1), LC(0.65, 0.25, 1.0, 1), LC(0.24, 0.21, 0.36, 1), 16.0),
    'Toxic':   (LC(0.35, 1.0, 0.25, 1), LC(0.65, 1.0, 0.20, 1), LC(0.20, 0.24, 0.18, 1), 12.0),
}

def fresh(name, cls=unreal.Material, factory=None):
    p = ROOT + '/' + name
    if EAL.does_asset_exist(p): EAL.delete_asset(p)
    return AT.create_asset(name, ROOT, cls, factory or unreal.MaterialFactoryNew())
def E(m, cls): return MEL.create_material_expression(m, cls, 0, 0)
def C(a, ao, b, bi):
    if not MEL.connect_material_expressions(a, ao, b, bi): log('CONNECT FAILED %s.%s -> %s.%s' % (a.get_class().get_name(), ao, b.get_class().get_name(), bi))
def S(m, n, v):
    e = E(m, unreal.MaterialExpressionScalarParameter); e.set_editor_property('parameter_name', n); e.set_editor_property('default_value', v); return e
def V(m, n, v):
    e = E(m, unreal.MaterialExpressionVectorParameter); e.set_editor_property('parameter_name', n); e.set_editor_property('default_value', v); return e
def K(m, v):
    e = E(m, unreal.MaterialExpressionConstant); e.set_editor_property('r', v); return e
def K3(m, r, g, b):
    e = E(m, unreal.MaterialExpressionConstant3Vector); e.set_editor_property('constant', LC(r, g, b, 1)); return e
def O(m, cls, a, b, ao='', bo=''):
    e = E(m, cls)
    if a is not None: C(a, ao, e, 'A')
    if b is not None: C(b, bo, e, 'B')
    return e
def U(m, cls, a, ao=''):
    e = E(m, cls); C(a, ao, e, ''); return e
MUL, ADD, SUB = unreal.MaterialExpressionMultiply, unreal.MaterialExpressionAdd, unreal.MaterialExpressionSubtract
SAT, OM = unreal.MaterialExpressionSaturate, unreal.MaterialExpressionOneMinus
def TS(m, tex, uv, vertex=False):
    e = E(m, unreal.MaterialExpressionTextureSample); e.set_editor_property('texture', tex)
    e.set_editor_property('sampler_type', unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR)
    if vertex:
        e.set_editor_property('mip_value_mode', unreal.TextureMipValueMode.TMVM_MIP_LEVEL)
        e.set_editor_property('const_mip_value', 0)
    C(uv, '', e, 'UVs'); return e
def finish(m):
    MEL.recompile_material(m); EAL.save_loaded_asset(m); return m

def import_tex(name):
    t = unreal.AssetImportTask()
    t.set_editor_property('filename', os.path.join(HERE, name + '.png')); t.set_editor_property('destination_path', ROOT)
    t.set_editor_property('automated', True); t.set_editor_property('replace_existing', True); t.set_editor_property('save', False)
    AT.import_asset_tasks([t])
    a = unreal.load_asset(ROOT + '/' + name)
    a.set_editor_property('srgb', False)

    EAL.save_loaded_asset(a)
    return a

def build_master(cells):
    # Masked, lit stone patch on a grid disc (AZoogiCrackFX builds it, UV0 0..1 across the disc).
    # Texture: R = seam glow, G = cell bevel (0 at seam), B = per-cell random, A = stone / flicker noise.
    m = fresh('M_ZoogiCrack')
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_MASKED)
    m.set_editor_property('opacity_mask_clip_value', 0.5)
    tc = E(m, unreal.MaterialExpressionTextureCoordinate)
    cuv = O(m, MUL, tc, S(m, 'CellDensity', 2.4))
    tp = TS(m, cells, cuv)
    tv = TS(m, cells, cuv, vertex=True)
    half = E(m, unreal.MaterialExpressionConstant2Vector); half.set_editor_property('r', 0.5); half.set_editor_property('g', 0.5)
    r = O(m, MUL, U(m, unreal.MaterialExpressionLength, O(m, SUB, tc, half)), K(m, 2.0))  # 0 centre .. 1 disc edge
    # ---- crater: cells tilt up into a raised rim around a low centre (WPO, vertex texture fetch at mip 0)
    rimR = S(m, 'RimRadius', 0.72)
    inner = U(m, SAT, O(m, unreal.MaterialExpressionDivide, r, rimR))
    outer = U(m, SAT, O(m, unreal.MaterialExpressionDivide, U(m, OM, r), U(m, OM, rimR)))
    prof = O(m, MUL, O(m, MUL, inner, inner), outer)
    cellh = O(m, ADD, O(m, MUL, tv, K(m, 0.45), 'B', ''), K(m, 0.55))
    z = O(m, MUL, O(m, ADD, O(m, MUL, prof, cellh), O(m, MUL, tv, K(m, 0.10), 'B', '')), tv, '', 'G')  # seams stay low = cell walls
    z = O(m, MUL, O(m, MUL, z, S(m, 'ExtrudeDepth', 40.0)), S(m, 'Rise', 1.0))
    MEL.connect_material_property(O(m, MUL, K3(m, 0, 0, 1), z), '', MP.MP_WORLD_POSITION_OFFSET)
    # ---- soft irregular edge (opacity mask)
    pan = E(m, unreal.MaterialExpressionPanner); pan.set_editor_property('speed_x', 0.03); pan.set_editor_property('speed_y', 0.05)
    C(O(m, MUL, tc, K(m, 1.3)), '', pan, 'Coordinate')
    fl = TS(m, cells, pan)
    edge = O(m, ADD, O(m, SUB, S(m, 'RadiusMask', 1.0), r), O(m, MUL, O(m, SUB, tp, K(m, 0.5), 'A', ''), K(m, 0.35)))
    edge = O(m, SUB, edge, O(m, MUL, U(m, OM, tp, 'G'), K(m, 0.06)))  # break along seams near the edge
    MEL.connect_material_property(U(m, SAT, O(m, ADD, O(m, MUL, edge, K(m, 10.0)), K(m, 0.5))), '', MP.MP_OPACITY_MASK)
    # ---- bevelled stone
    bev = O(m, ADD, O(m, MUL, tp, K(m, 0.65), 'G', ''), K(m, 0.35))
    var = O(m, ADD, O(m, MUL, tp, K(m, 0.5), 'A', ''), K(m, 0.65))
    stone = O(m, MUL, O(m, MUL, V(m, 'StoneColor', LC(0.4, 0.38, 0.35, 1)), bev), var)
    MEL.connect_material_property(stone, '', MP.MP_BASE_COLOR)
    MEL.connect_material_property(S(m, 'Roughness', 0.82), '', MP.MP_ROUGHNESS)
    # ---- glowing seams (noise-panned flicker) + hot bowl
    pw = E(m, unreal.MaterialExpressionPower); C(tp, 'R', pw, 'Base'); C(S(m, 'SeamSharp', 4.0), '', pw, 'Exp')
    seam = U(m, SAT, pw)
    flick = O(m, ADD, O(m, MUL, fl, K(m, 1.3), 'A', ''), K(m, 0.35))
    inside = U(m, SAT, O(m, MUL, O(m, SUB, S(m, 'RadiusMask', 1.0), r), K(m, 4.0)))
    glow = O(m, MUL, S(m, 'Emissive', 10.0), S(m, 'Glow', 1.0))
    e1 = O(m, MUL, O(m, MUL, O(m, MUL, V(m, 'CrackColor', LC(1, 0.4, 0.1, 1)), seam), flick), inside)
    bowl = O(m, MUL, O(m, MUL, U(m, OM, inner), U(m, OM, tp, 'G')), K(m, 0.18))
    e2 = O(m, MUL, V(m, 'InnerColor', LC(1, 0.3, 0.05, 1)), bowl)
    MEL.connect_material_property(O(m, MUL, O(m, ADD, e1, e2), glow), '', MP.MP_EMISSIVE_COLOR)
    finish(m)
    for n, (cc, ic, sc, em) in STYLES.items():
        mi = fresh('MI_ZoogiCrack_' + n, unreal.MaterialInstanceConstant, unreal.MaterialInstanceConstantFactoryNew())
        MEL.set_material_instance_parent(mi, m)
        MEL.set_material_instance_vector_parameter_value(mi, 'CrackColor', cc)
        MEL.set_material_instance_vector_parameter_value(mi, 'InnerColor', ic)
        MEL.set_material_instance_vector_parameter_value(mi, 'StoneColor', sc)
        MEL.set_material_instance_scalar_parameter_value(mi, 'Emissive', em)
        if n == 'Crystal': MEL.set_material_instance_scalar_parameter_value(mi, 'CellDensity', 1.8)
        EAL.save_loaded_asset(mi)

def build_shaft(soft):
    # additive vertical light shaft card (AZoogiCrackFX procedural section 1: UV x across, y = 0 top .. 1 bottom)
    m = fresh('M_ZoogiCrackShaft')
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_ADDITIVE)
    m.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property('two_sided', True)
    tc = E(m, unreal.MaterialExpressionTextureCoordinate)
    t = TS(m, soft, tc)
    vc = E(m, unreal.MaterialExpressionVertexColor)
    e = O(m, MUL, O(m, MUL, O(m, MUL, V(m, 'Color', LC(1, 0.5, 0.2, 1)), t, '', 'R'), vc, '', 'A'), S(m, 'Intensity', 3.0))
    MEL.connect_material_property(e, '', MP.MP_EMISSIVE_COLOR)
    finish(m)

def build_spark(soft):
    m = fresh('M_ZoogiCrackSpark')
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_ADDITIVE)
    m.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property('used_with_niagara_sprites', True)
    tc = E(m, unreal.MaterialExpressionTextureCoordinate)
    t = TS(m, soft, tc)
    pc = E(m, unreal.MaterialExpressionParticleColor)
    e = O(m, MUL, O(m, MUL, O(m, MUL, pc, t, 'RGB', 'G'), pc, '', 'A'), S(m, 'Glow', 12.0))
    MEL.connect_material_property(e, '', MP.MP_EMISSIVE_COLOR)
    finish(m)
    return m

def system(name, tpl, mat, cfg):
    p = ROOT + '/' + name
    if EAL.does_asset_exist(p): EAL.delete_asset(p)
    s = AT.create_asset(name, ROOT, unreal.NiagaraSystem, unreal.NiagaraSystemFactoryNew())
    en = 'KSparks'
    if not L.add_emitter_from_asset(s, unreal.load_asset(TPL + tpl), en): log('add emitter FAILED ' + name); return
    L.set_emitter_local_space(s, en, False)
    L.set_niagara_float(s, en, 'EmitterState.MaxDistance', 1000000.0)
    L.set_emitter_render(s, en, mat, None)
    for k, v in cfg.items():
        if isinstance(v, int) and not isinstance(v, bool): n = L.set_niagara_int(s, en, k, v)
        elif isinstance(v, unreal.LinearColor): n = L.set_niagara_color(s, en, k, v)
        elif isinstance(v, unreal.Vector): n = L.set_niagara_vector(s, en, k, v)
        else: n = L.set_niagara_float(s, en, k, float(v))
        if not n: log('%s: input not found %s' % (name, k))
    log('%s compile: %s' % (name, L.compile_report(s)))
    EAL.save_loaded_asset(s)

def build_sparks(spark):
    # sparks rising off the seams: a flat disc burst (component scale = crater radius / 100) drifting up
    for n, (cc, ic, sc, em) in STYLES.items():
        system('NS_ZoogiCrackSparks_' + n, 'OmnidirectionalBurst', spark, {
            'SpawnBurst_Instantaneous.Spawn Count': 26, 'InitializeParticle.Lifetime Min': 0.8, 'InitializeParticle.Lifetime Max': 1.8,
            'Uniform Sprite Size Min': 3.0, 'Uniform Sprite Size Max': 8.0, 'InitializeParticle.Color': LC(cc.r, cc.g, cc.b, 1.0),
            'RandomRangeFloat.Minimum': 20.0, 'RandomRangeFloat.Maximum': 90.0, 'GravityForce.Gravity': unreal.Vector(0, 0, 260), 'Drag.Drag': 1.2,
            'ShapeLocation.Sphere Radius': 70.0, 'ShapeLocation.Non Uniform Scale': unreal.Vector(1, 1, 0.05)})

cells = import_tex('T_ZoogiCrackCells')
soft = import_tex('T_ZoogiCrackSoft')
build_master(cells)
build_shaft(soft)
build_sparks(build_spark(soft))
log('done')
